/**
 * Generates TypeScript types for the api from its OpenAPI document (ADR-009).
 *
 * Usage: node scripts/generate-api.ts <openapi.json> <output.ts>
 *
 * The document is written by `cargo run -p rampsmith-api --bin gen-openapi`; CI regenerates
 * both and diffs them against the committed files (PLAN §24).
 */
import { readFileSync, writeFileSync } from 'node:fs';
import process from 'node:process';
import openapiTS, { astToString, type OpenAPI3 } from 'openapi-typescript';

const BANNER =
  '/* Generated by packages/contracts-ts/scripts/generate-api.ts from crates/api. Do not edit. */\n';

const [input, output] = process.argv.slice(2);
if (input === undefined || output === undefined) {
  throw new Error('usage: node scripts/generate-api.ts <openapi.json> <output.ts>');
}

const document = JSON.parse(readFileSync(input, 'utf8')) as OpenAPI3;
const ast = await openapiTS(document, { alphabetize: true });
writeFileSync(output, BANNER + astToString(ast));
